import{_ as e,c as o,o as s,ag as n}from"./chunks/framework.Cycwnjj0.js";const a="/assets/download-the-azonpress-zip-file.Cu4KjnAt.webp",r="/assets/add-new-plugin-from-wordpress-dashboard.DPh2RSsG.webp",i="/assets/upload-plugin-button.-UDJVVSt.webp",l="/assets/choose-file-button.CgsAZJ_8.webp",p="/assets/install-now-button.CEQ6WUOY.webp",g="/assets/activate-plugin-button.DPgtNOyY.webp",h="/assets/activate-azonpress-license-key.D4G-vKub.webp",c="/assets/update-option-for-azonpress-plugin.BG51lThP.webp",z=JSON.parse('{"title":"How to Install, Activate, and Update the AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/how-to-install-activate-and-update-the-azonpress.md","filePath":"guide/getting-started/how-to-install-activate-and-update-the-azonpress.md"}'),d={name:"guide/getting-started/how-to-install-activate-and-update-the-azonpress.md"};function u(w,t,f,P,A,b){return s(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="how-to-install-activate-and-update-the-azonpress" tabindex="-1">How to Install, Activate, and Update the AzonPress <a class="header-anchor" href="#how-to-install-activate-and-update-the-azonpress" aria-label="Permalink to &quot;How to Install, Activate, and Update the AzonPress&quot;">​</a></h1><p>This article will guide you through installing, activating, and updating AzonPress on your WordPress website. Please follow the instructions for a successful installation.</p><h2 id="get-the-zip-file-to-install-azonpress" tabindex="-1">Get The Zip File To Install AzonPress <a class="header-anchor" href="#get-the-zip-file-to-install-azonpress" aria-label="Permalink to &quot;Get The Zip File To Install AzonPress&quot;">​</a></h2><p>To learn how to get the .zip file to install the <strong>AzonPress Plugin</strong>, follow the steps with the screenshots below –</p><p>First, to purchase the <strong>AzonPress</strong> plugin, click here.</p><p>Once you have purchased the plugin, you will get access to the WP Manage Ninja Dashboard. Now, log into the account with your credentials.</p><p>Then, go to the <strong>Dashboard</strong> and you will find <strong>AzonPress</strong> under <strong>My Products</strong> if you have already purchased the product.</p><p>Now, click the <strong>Download</strong> button and the <strong>AzonPress .zip file</strong> will be downloaded to your device.</p><p>You&#39;ll also see a <strong>License Key</strong> that you can copy as you need it later to activate the plugin, or you retrieve it anytime from your <strong>WP Manage Ninja Dashboard.</strong></p><p><img src="'+a+'" alt="Download the AzonPress Zip file"></p><h2 id="installing-and-activating-azonpress" tabindex="-1">Installing And Activating AzonPress <a class="header-anchor" href="#installing-and-activating-azonpress" aria-label="Permalink to &quot;Installing And Activating AzonPress&quot;">​</a></h2><p>To learn how to install and activate <strong>AzonPress</strong> from the <strong>WordPress Plugin Directory</strong> on your <strong>WordPress Site</strong>, follow the steps with the screenshots below –</p><p>First, go to <strong>Plugins</strong> from your WordPress dashboard, and click on <strong>Add New Plugin.</strong></p><p><img src="'+r+'" alt="Add new Plugin from WordPress Dashboard"></p><p>Click on the <strong>Upload</strong> button.</p><p><img src="'+i+'" alt="Upload Plugin button"></p><p>Click on the <strong>Choose file</strong> to upload the <strong>AzonPress zip file</strong> that you&#39;ve downloaded before.</p><p><img src="'+l+'" alt="Choose file button"></p><p>Click the <strong>Install Now</strong> button and the <strong>AzonPress</strong> plugin will be successfully <strong>installed</strong> on your WordPress site.</p><p><img src="'+p+'" alt="Install Now button"></p><p>Now, to activate, click on the <strong>Activate Plugin.</strong> But, you need the <strong>License key</strong> to activate all the <strong>AzonPress</strong> features successfully. Keep reading to learn how to activate the license.</p><p><img src="'+g+'" alt="Activate plugin button"></p><h2 id="how-to-activate-the-license-key" tabindex="-1">How to Activate The License Key <a class="header-anchor" href="#how-to-activate-the-license-key" aria-label="Permalink to &quot;How to Activate The License Key&quot;">​</a></h2><p>To activate the license, follow the steps in the screenshot below –</p><p>First, go to <strong>Settings</strong> from your <strong>AzonPress Dashboard</strong>, open <strong>Licensing</strong> from the left sidebar, and enter the <strong>License Key</strong> you&#39;ve copied before into the input field.</p><p>And finally, click the <strong>Activate AzonPress</strong> button. Your <strong>AzonPress</strong> plugin will also be successfully <strong>Activated</strong> on your WordPress site!</p><p><img src="'+h+'" alt="Activate AzonPress License key"></p><h2 id="how-to-update-azonpress" tabindex="-1">How to Update AzonPress <a class="header-anchor" href="#how-to-update-azonpress" aria-label="Permalink to &quot;How to Update AzonPress&quot;">​</a></h2><p>For updating with the latest version of AzonPress, we have implemented an automatic update system compatible with the previous version. Also, you can manually update it anytime if needed.</p><p>To <strong>Update</strong> the <strong>AzonPress</strong> plugin <strong>manually</strong>, follow the steps in the screenshot below –</p><p>Go to the <strong>Plugins</strong> page of your <strong>WordPress Dashboard</strong> and search for <strong>AzonPress</strong> from the <strong>Search Bar</strong> in the top right corner.</p><p>Now, check if any update is available. If yes, just click on the <strong>Update</strong> button.</p><p><img src="'+c+'" alt="Update option for AzonPress Plugin"></p><p>Congratulations now you can explore all the amazing features of the AzonPress!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',36)])])}const m=e(d,[["render",u]]);export{z as __pageData,m as default};
